import java.util.*; public class Main { public static void main(String[] a){Scanner s=new Scanner(System.in);double bal=10000;System.out.println("1 Balance 2 Deposit 3 Withdraw");int c=s.nextInt();if(c==1)System.out.println(bal);else if(c==2){bal+=s.nextDouble();System.out.println(bal);}else if(c==3){double x=s.nextDouble();if(x<=bal){bal-=x;System.out.println(bal);}else System.out.println("Insufficient balance");}}}